def check():
    pins=json.loads((HERE/'pins.json').read_bytes())
    if type(pins) is not dict or set(pins)!={'schema','profile','sources','own'} or type(pins['schema']) is not int or pins['schema']!=1 or pins['profile']!='attention-bank-scratch-model-v1':raise ValueError('source contract')
    if set(pins['sources'])!=set(SOURCES) or set(pins['own'])!=set(OWN):raise ValueError('source inventory')
    for group in ('sources','own'):
        for name,digest in pins[group].items():
            if hashlib.sha256((ROOT/name).read_bytes()).hexdigest()!=digest:raise ValueError('source drift')
    name='candidates/qwen2_resident_matrix/raw_kv/model.py'
    original=(ROOT/name).read_text()
    variant=(HERE/'port.py').read_text()
    patch=''.join(difflib.unified_diff(original.splitlines(True),variant.splitlines(True),fromfile='a/'+name,tofile='b/'+name))
    if patch!=(HERE/'route.patch').read_text():raise ValueError('explicit model adaptation')
    chisel=(ROOT/'candidates/qwen2_resident_matrix/raw_kv_parent/integration.patch').read_text()
    if not all(x in chisel for x in ('val line=UInt(13.W)','p.request.bits.key.line<4096.U','p.ack.bits.line<4096.U')):raise ValueError('existing hardware range')
    return dict(status='PASS_SOURCE_ONLY',sources=len(SOURCES),own=len(OWN),chisel_scratch_route_implemented=False)

